customModelExample:
const models = {
  RequisitionListModel: {
    transformer: (data) => ({
      // Add formatted last updated date
      lastUpdatedDisplay: data?.updated_at ? 
        new Date(data.updated_at).toLocaleDateString() : null,
      // Add total items summary
      itemsSummary: `${data?.items_count || 0} items`,
      // Add list description preview (first 50 chars)
      descriptionPreview: data?.description ? 
        data.description.substring(0, 50) + '...' : null,
    }),
  },
};

await initializers.mountImmediately(initialize, { models });

RequisitionListModel.definition:
export interface RequisitionList {
  uid: string;
  name: string;
  description: string;
  updated_at: string;
  items_count: number;
  items: Item[];
  page_info?: PageInfo;
}

export interface PageInfo {
  page_size: number;
  current_page: number;
  total_pages: number;
}

RequisitionListItemModel.definition:
export interface Item {
  uid: string;
  sku: string;
  product: Product;
  quantity: number;
  customizable_options?: {
    uid: string;
    is_required: boolean;
    label: string;
    sort_order: number;
    type: string;
    values: {
      uid: string;
      label: string;
      price: { type: string; units: string; value: number };
      value: string;
    }[];
  }[];
  bundle_options?: {
    uid: string;
    label: string;
    type: string;
    values: {
      uid: string;
      label: string;
      original_price: { value: number; currency: string };
      priceV2: { value: number; currency: string };
      quantity: number;
    }[];
  }[];
  configurable_options?: {
    option_uid: string;
    option_label: string;
    value_uid: string;
    value_label: string;
  }[];
  links?: {
    uid: string;
    price?: number;
    sample_url?: string;
    sort_order?: number;
    title?: string;
  }[];
  samples?: {
    url?: string;
    sort_order?: number;
    title?: string;
  }[];
  gift_card_options?: {
    amount?: { value?: number; currency?: string; };
    custom_giftcard_amount?: { value?: number; currency?: string; };
    message?: string;
    recipient_email?: string;
    recipient_name?: string;
    sender_name?: string;
    sender_email?: string;
  };
}

export interface Product {
  sku: string;
  parent_sku: string;
  name: string;
  shortDescription: string;
  metaDescription: string;
  metaKeyword: string;
  metaTitle: string;
  description: string;
  addToCartAllowed: boolean;
  url: string;
  urlKey: string;
  externalId: string;
  images: {
    url: string;
    label: string;
    roles: string[];
  }[];
}
